#!/usr/bin/env python3
import cadquery as cq
from pathlib import Path

SPEC = {'kind': 'extrusion', 'center': [1.1149999999959803e-06, -0.298681885, 1.080000000000525e-06], 'basis': [[-0.0, 0.9999136873833748, -0.013138408708158626], [0.17510160196160715, 0.012935425140972736, 0.9844653898268345], [0.9845503689453775, -0.002300556412024905, -0.17508648848416658]], 'axis': [-0.013138408708158626, 0.9844653898268345, -0.17508648848416658], 'zmin': -0.2228728010234091, 'zmax': 0.2306744775053217, 'profiles': [{'outer': [[-0.1934980570800249, -0.0007495853671696172], [-0.1926027857385355, 0.015442804782092453], [-0.19015891512173186, 0.03148414911210625], [-0.18616644522961412, 0.04717782459538469], [-0.18067378640382317, 0.062401094954654644], [-0.17375350000655038, 0.07698206459359876], [-0.1654540160704442, 0.09082262515507525], [-0.15584789595769574, 0.10377542892379202], [-0.14503194066057992, 0.11566870693708868], [-0.13312713172843263, 0.12645361612787603], [-0.11750040384010495, 0.1379362424356811], [-0.10392540977759855, 0.15021850210350596], [-0.08899600303902891, 0.16126665051407255], [-0.06122714356095575, 0.17797366653873012], [-0.04382966595751383, 0.18611625822452374], [-0.025730479615117166, 0.19248787298706335], [-0.007123166827307792, 0.1970644052815886], [0.011847100454013293, 0.19974781281744078], [0.03101094018337273, 0.20051398349786717], [0.05012637941659481, 0.19936346273234348], [0.06907245629535091, 0.1963457189215129], [0.08763138827803031, 0.19143661307605972], [0.10563378347365596, 0.1847103446359804], [0.12300549857048428, 0.17615522935356526], [0.13926727445579862, 0.16607810625941863], [0.15458384578145232, 0.1543449364060125], [0.16878578127445365, 0.14107896509173165], [0.18153747089745667, 0.1265257324321995], [0.19397934958299323, 0.10933321971301883], [0.20356126944767294, 0.09282143341968571], [0.2114978185812748, 0.07545339603674624], [0.2177163765485855, 0.057376724525582914], [0.22216860192648968, 0.03876354699515615], [0.22480605483683533, 0.019785981785345092], [0.22560453503155373, 0.0006652663514755598], [0.22453988164459093, -0.01845108557931968], [0.22163624569649723, -0.037341969530313955], [0.2169420867564321, -0.05588463934012507], [0.21045735559687706, -0.0738333361076401], [0.20227883351909942, -0.09106541658364871], [0.1913371929947545, -0.10946006782253413], [0.1798195191131802, -0.12496413433521665], [0.1668742471966351, -0.13926072898220723], [0.15247871956458808, -0.15228886556131285], [0.13699278588446837, -0.1637288996195148], [0.12049058946801956, -0.17359379478149745], [0.10311730226714264, -0.18173646299023585], [0.08501812577024966, -0.18813264565508003], [0.06641082282794399, -0.1926845800959012], [0.04744055554662289, -0.19536799763089022], [0.028276715817263456, -0.19613417831045354], [0.009161256893033994, -0.19498366749805562], [-0.009784810140218418, -0.19196589371281994], [-0.02834372243189044, -0.18705680791165166], [-0.04634611762751607, -0.18033051947329862], [-0.04923856034612208, -0.17890647386743014], [-0.05243862824801376, -0.17771192236592756], [-0.05446707133900395, -0.17671387075226244], [-0.05870164416967556, -0.17512866545270603], [-0.07537322263159775, -0.16693103395131334], [-0.09117371030909181, -0.15713810577202741], [-0.09582137902050565, -0.1535735790724048], [-0.10847062332777856, -0.14731309108526489], [-0.1221176039832784, -0.13885219036668234], [-0.13489349385435012, -0.12906632963472756], [-0.14662893058652776, -0.11805417614831054], [-0.15727549399266655, -0.10593871244270134], [-0.1667122419054453, -0.09281853263199313], [-0.17481815339351317, -0.07884136677292161], [-0.18154485749724392, -0.06410560940815625], [-0.18681975347243152, -0.048783475329778024], [-0.19059445066844227, -0.03302249488506553], [-0.19284475868271117, -0.016945613990869215]], 'holes': []}], 'simplify_tolerance': 8.382051842231573e-05, 'sketch_entity_count': 73}
OUT = Path(__file__).resolve().parent

def vec(v):
    return cq.Vector(float(v[0]), float(v[1]), float(v[2]))

def build():
    s = SPEC
    kind = s["kind"]
    B = s.get("basis")
    center = s.get("center")
    if kind == "extrusion":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["zmin"] * axis[i] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        result = None
        height = s["zmax"] - s["zmin"]
        for profile in s["profiles"]:
            solid = cq.Workplane(plane).polyline(profile["outer"]).close().extrude(height)
            for hole in profile["holes"]:
                cutter = cq.Workplane(plane).polyline(hole).close().extrude(height)
                solid = solid.cut(cutter)
            result = solid if result is None else result.union(solid)
    elif kind == "multi_loft":
        def loft(track):
            wires = [cq.Wire.makePolygon([vec(p) for p in section], close=True) for section in track]
            return cq.Solid.makeLoft(wires, ruled=bool(s.get("ruled", True)))
        outer = [loft(track) for track in s["outer_tracks"]]
        # Keep disjoint solids as a legal STEP compound.  Global Boolean fusion
        # is unnecessary for training geometry and scales poorly with profiles.
        for track in s.get("hole_tracks", []):
            cutter = loft(track)
            cut_outer = []
            for solid in outer:
                try:
                    cut_outer.append(solid.cut(cutter))
                except Exception:
                    cut_outer.append(solid)
            outer = cut_outer
        result = outer[0] if len(outer) == 1 else cq.Compound.makeCompound(outer)
    elif kind == "box":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["mins"][0]*B[i][0] + s["mins"][1]*B[i][1] + s["mins"][2]*B[i][2] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        dx=s["maxs"][0]-s["mins"][0]; dy=s["maxs"][1]-s["mins"][1]; dz=s["maxs"][2]-s["mins"][2]
        result = cq.Workplane(plane).rect(dx,dy,centered=False).extrude(dz)
    elif kind == "cylinder":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["zmin"] * axis[i] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        result = cq.Workplane(plane).circle(s["radius"]).extrude(s["zmax"]-s["zmin"])
    else:
        raise ValueError(kind)
    cq.exporters.export(result, str(OUT / "reconstructed.step"))
    cq.exporters.export(result, str(OUT / "reconstructed.stl"), tolerance=0.001, angularTolerance=0.05)
    return result

if __name__ == "__main__":
    build()
